(912, 598, '_elementor_data', '[{\"id\":\"dc928b9\",\"elType\":\"section\",\"settings\":{\"gap\":\"no\",\"margin\":{\"unit\":\"px\",\"top\":\"\",\"right\":0,\"bottom\":\"\",\"left\":0,\"isLinked\":true}},\"elements\":[{\"id\":\"fdc78fa\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"bae8cd3\",\"elType\":\"widget\",\"settings\":{\"image_rounded\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"40\",\"left\":\"0\",\"isLinked\":false},\"thumbnail\":\"agrios-project-standard\"},\"elements\":[],\"widgetType\":\"mae-post-featured_image\"},{\"id\":\"ae6c75d\",\"elType\":\"section\",\"settings\":{\"reverse_order_tablet\":\"reverse-tablet\",\"reverse_order_mobile\":\"reverse-mobile\"},\"elements\":[{\"id\":\"3b48525\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null,\"_inline_size_tablet\":100},\"elements\":[{\"id\":\"12ed970\",\"elType\":\"widget\",\"settings\":[],\"elements\":[],\"widgetType\":\"mae-post-content-title\"},{\"id\":\"37a5183\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p data-sourcepos=\\\"3:1-3:91\\\"><strong>Norsworthy Farms<\\/strong> offers high-quality Technical Palm Oil (TPO), a versatile product with a wide range of industrial applications. Our TPO is produced using advanced processing techniques to ensure consistent quality and performance.<\\/p><p data-sourcepos=\\\"5:1-5:28\\\"><strong>Key Features of Our TPO:<\\/strong><\\/p><ul data-sourcepos=\\\"7:1-7:155\\\"><li data-sourcepos=\\\"7:1-7:155\\\"><strong>Purity and Quality:<\\/strong> Our TPO is refined to remove impurities and contaminants, resulting in a product with excellent physical and chemical properties.<\\/li><li data-sourcepos=\\\"8:1-9:72\\\"><strong>Versatility:<\\/strong> TPO can be used in various industrial applications, including:<ul data-sourcepos=\\\"9:5-9:72\\\"><li data-sourcepos=\\\"9:5-9:72\\\"><strong>Biodiesel production:<\\/strong> TPO is a popular feedstock for biodiesel, a renewable fuel alternative.<\\/li><li data-sourcepos=\\\"10:5-10:139\\\"><strong>Oleochemicals:<\\/strong> TPO is used as a raw material for the production of oleochemicals, such as fatty acids, glycerin, and surfactants.<\\/li><li data-sourcepos=\\\"11:5-11:139\\\"><strong>Lubricants and greases:<\\/strong> TPO can be used as a base oil for lubricants and greases, providing excellent performance and durability.<\\/li><li data-sourcepos=\\\"12:5-12:115\\\"><strong>Food processing:<\\/strong> TPO is used as an ingredient in certain food products, such as margarine and shortening.<\\/li><\\/ul><\\/li><li data-sourcepos=\\\"13:1-14:0\\\"><strong>Sustainability:<\\/strong> Our TPO is sourced from sustainably managed palm oil plantations, ensuring that our product is produced in an environmentally responsible manner.<\\/li><\\/ul>\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false}],\"isInner\":false},{\"id\":\"9987b91\",\"elType\":\"section\",\"settings\":{\"content_width\":{\"unit\":\"px\",\"size\":1540,\"sizes\":[]}},\"elements\":[{\"id\":\"4bb1783\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"64cc116\",\"elType\":\"widget\",\"settings\":{\"space\":{\"unit\":\"px\",\"size\":110,\"sizes\":[]},\"space_mobile\":{\"unit\":\"px\",\"size\":80,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"spacer\"},{\"id\":\"cac22fc\",\"elType\":\"widget\",\"settings\":{\"align\":\"center\",\"pre\":\"Other Services\",\"heading\":\"\",\"sub\":\"\",\"heading_bottom_space\":{\"unit\":\"px\",\"size\":50,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"mae-headings\"},{\"id\":\"c3a6a0d\",\"elType\":\"widget\",\"settings\":{\"url_text\":\"Read More\",\"column\":{\"unit\":\"px\",\"size\":4,\"sizes\":[]},\"column_tablet\":{\"unit\":\"px\",\"size\":3,\"sizes\":[]},\"column_mobile\":{\"unit\":\"px\",\"size\":1,\"sizes\":[]},\"gap\":{\"unit\":\"px\",\"size\":10,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"mae-project-related\"}],\"isInner\":false}],\"isInner\":false}]'),
