(1159, 611, '_elementor_data', '[{\"id\":\"51237c1\",\"elType\":\"section\",\"settings\":{\"gap\":\"no\",\"margin\":{\"unit\":\"px\",\"top\":\"\",\"right\":0,\"bottom\":\"\",\"left\":0,\"isLinked\":true}},\"elements\":[{\"id\":\"991f6df\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"00fc639\",\"elType\":\"widget\",\"settings\":{\"image_rounded\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"40\",\"left\":\"0\",\"isLinked\":false},\"thumbnail\":\"agrios-project-standard\"},\"elements\":[],\"widgetType\":\"mae-post-featured_image\"},{\"id\":\"117e311\",\"elType\":\"section\",\"settings\":{\"reverse_order_tablet\":\"reverse-tablet\",\"reverse_order_mobile\":\"reverse-mobile\"},\"elements\":[{\"id\":\"7e2c28d\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null,\"_inline_size_tablet\":100},\"elements\":[{\"id\":\"4a60f44\",\"elType\":\"widget\",\"settings\":[],\"elements\":[],\"widgetType\":\"mae-post-content-title\"},{\"id\":\"4c4998f\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p data-sourcepos=\\\"3:1-3:101\\\"><strong>Norsworthy Farms<\\/strong> is committed to providing premium quality oil palm seedlings that are cultivated using advanced agricultural techniques and the latest scientific research. Our high-breed oil palm seedlings are renowned for their:<\\/p><ul data-sourcepos=\\\"5:1-5:45\\\"><li data-sourcepos=\\\"5:1-5:45\\\"><strong>High Yield Potential:<\\/strong> Our seedlings are carefully selected and nurtured to produce maximum yield per hectare.<\\/li><li data-sourcepos=\\\"6:1-6:136\\\"><strong>Disease Resistance:<\\/strong> We employ rigorous quality control measures to ensure our seedlings are resistant to common oil palm diseases.<\\/li><li data-sourcepos=\\\"7:1-7:113\\\"><strong>Early Maturity:<\\/strong> Our seedlings are bred to reach maturity sooner, allowing for faster returns on investment.<\\/li><li data-sourcepos=\\\"8:1-8:43\\\"><strong>Adaptability:<\\/strong> Our seedlings are well-suited to various soil types and climatic conditions, ensuring optimal growth in different regions.<\\/li><\\/ul>\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false}],\"isInner\":false},{\"id\":\"834740b\",\"elType\":\"section\",\"settings\":{\"content_width\":{\"unit\":\"px\",\"size\":1540,\"sizes\":[]}},\"elements\":[{\"id\":\"70958a8\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"bfad449\",\"elType\":\"widget\",\"settings\":{\"space\":{\"unit\":\"px\",\"size\":110,\"sizes\":[]},\"space_mobile\":{\"unit\":\"px\",\"size\":80,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"spacer\"},{\"id\":\"252b31d\",\"elType\":\"widget\",\"settings\":{\"align\":\"center\",\"pre\":\"Other Services\",\"heading\":\"\",\"sub\":\"\",\"heading_bottom_space\":{\"unit\":\"px\",\"size\":50,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"mae-headings\"},{\"id\":\"c2a0f0b\",\"elType\":\"widget\",\"settings\":{\"url_text\":\"Read More\",\"column\":{\"unit\":\"px\",\"size\":4,\"sizes\":[]},\"column_tablet\":{\"unit\":\"px\",\"size\":3,\"sizes\":[]},\"column_mobile\":{\"unit\":\"px\",\"size\":1,\"sizes\":[]},\"gap\":{\"unit\":\"px\",\"size\":10,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"mae-project-related\"}],\"isInner\":false}],\"isInner\":false}]'),
